package edu.ankara.audiometer.domain.algorithm;
import edu.ankara.audiometer.domain.config.*;import edu.ankara.audiometer.domain.model.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class HughsonWestlakeEngineTest { AudiometryConfig c=AudiometryConfig.defaults(); @Test void heardResponseDecreasesIntensityBy10Db(){ var s=HughsonWestlakeEngine.presentTone(TestState.initial(c)); var n=HughsonWestlakeEngine.applyResponseToLastPresentation(s,PatientResponse.HEARD); assertEquals(30,n.currentIntensity().value()); } @Test void noResponseIncreasesIntensityBy5Db(){ var s=HughsonWestlakeEngine.presentTone(TestState.initial(c)); var n=HughsonWestlakeEngine.applyResponseToLastPresentation(s,PatientResponse.NOT_HEARD); assertEquals(45,n.currentIntensity().value()); } @Test void rightAndLeftResultsAreIndependent(){ var p1=new AudiogramPoint(Ear.RIGHT,new FrequencyHz(1000),new IntensityDbHL(20),ThresholdCriterion.TWO_OUT_OF_THREE_ASCENDING,3,3,"right"); var p2=new AudiogramPoint(Ear.LEFT,new FrequencyHz(1000),new IntensityDbHL(35),ThresholdCriterion.TWO_OUT_OF_THREE_ASCENDING,3,6,"left"); var a=Audiogram.empty().add(p1,false).add(p2,false); assertEquals(2,a.points().size()); assertEquals(20,a.find(Ear.RIGHT,new FrequencyHz(1000)).orElseThrow().thresholdDbHL().value()); } @Test void audiogramPointCreationUsesCurrentEarAndFrequency(){ var s=TestState.initial(c); var p=AudiometryFunctions.createAudiogramPoint(s,new IntensityDbHL(25)); assertEquals(Ear.RIGHT,p.ear()); assertEquals(1000,p.frequency().value()); } }
